Here are the files. One design note first: since the extension can talk to your local system, background.js only accepts messages from `localhost` pages and uses an explicit command handler rather than running arbitrary shell input from any page — a Gradio app compromised or spoofed shouldn't become a remote shell. Adjust the handler to the commands you actually need.

**manifest.json** (as given — note the smart quotes in your paste would need to be straight quotes to parse):

```json
{
  "manifest_version": 2,
  "name": "Gradio Remote Interface Extension",
  "version": "1.0",
  "description": "Interface between Gradio app running in the browser and locally running Linux system",

  "background": {
    "scripts": ["background.js"]
  },

  "permissions": [
    "tabs",
    "webRequest",
    "webRequestBlocking",
    "http://localhost/",
    "https://localhost/"
  ],

  "browser_action": {
    "default_title": "Gradio Remote Interface",
    "default_icon": "icon.png",
    "default_popup": "popup.html"
  }
}
```

**background.js**

```javascript
// Background script: bridges messages from the Gradio page (content scripts
// or the page itself via externally_connectable / tabs API) to the local system.

const ALLOWED_ORIGINS = ["http://localhost", "https://localhost"];

// Explicit command handlers instead of arbitrary shell execution.
// Map whatever commands your Gradio app needs here.
const COMMANDS = {
  "ping": async (args) => ({ pong: true, args }),
  "listDir": async (args) => {
    const { exec } = require_browser(); // see helper below
    const dir = args && args.path ? args.path : ".";
    return runCommand("ls", ["-la", dir]);
  },
  "readFile": async (args) => runCommand("cat", [args.path]),
};

// Small helper so we don't need node integration: use child_process via
// a native messaging host would be the production-grade route; for a
// self-contained extension we shell out through the popup-side server.
// Simplest robust approach: extension talks to a tiny local HTTP API.
const LOCAL_API = "http://localhost:7861";

async function runCommand(command, args) {
  const response = await fetch(LOCAL_API + "/exec", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ command, args })
  });
  if (!response.ok) {
    throw new Error("Local API returned " + response.status);
  }
  return response.json();
}

// Listen for messages from content scripts on allowed pages.
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  const origin = sender.origin || (sender.url && new URL(sender.url).origin);
  if (!origin || !ALLOWED_ORIGINS.includes(origin)) {
    sendResponse({ error: "Origin not allowed: " + origin });
    return false;
  }

  const handler = COMMANDS[message && message.type];
  if (!handler) {
    sendResponse({ error: "Unknown command: " + (message && message.type) });
    return false;
  }

  handler(message.args)
    .then((result) => sendResponse({ ok: true, result }))
    .catch((err) => sendResponse({ ok: false, error: String(err) }));

  return true; // keep the message channel open for the async response
});

// Track Gradio tabs so the popup can show connection status.
let gradioTabs = new Set();

chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
  if (tab.url && tab.url.startsWith("http://localhost")) {
    gradioTabs.add(tabId);
  } else {
    gradioTabs.delete(tabId);
  }
});

chrome.tabs.onRemoved.addListener((tabId) => gradioTabs.delete(tabId));

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message && message.type === "getStatus") {
    sendResponse({ connectedTabs: [...gradioTabs] });
  }
});
```

