# Mesh Surface Flattening in C

**What this does:** reads a Wavefront OBJ mesh, splits it into connected "surfaces" (patches of faces joined by shared edges), and flattens each one into 2D. Distances are preserved *locally and exactly* — each triangle is unfolded onto the plane with its true edge lengths, so the map is an isometry wherever the surface itself is developable. A final relaxation pass spreads out the inevitable distortion on non-developable regions (a sphere patch *cannot* be flattened with zero distortion — Gauss proved it — so the program minimizes it instead and reports the residual).

Each surface is written to its own output file (`surface_001.uv`, etc.), so overlap between surfaces doesn't matter.

```c
/* meshflat.c
 *
 * Flattens each connected surface of a triangular OBJ mesh into 2D,
 * preserving edge lengths (distances) exactly per triangle, then
 * relaxing to minimize total distortion (area + length).
 *
 * Build:  cc -O2 -o meshflat meshflat.c -lm
 * Usage:  meshflat model.obj outdir
 * Output: outdir/surface_NNN.uv  (one per surface: 2D coords + stats)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAXV 200000
#define MAXF 400000

typedef struct { double x, y, z; } Vec3;
typedef struct { double x, y; } Vec2;

typedef struct {
    int v[3];          /* vertex indices */
    int adj[3];        /* face across edge (v0,v1),(v1,v2),(v2,v0); -1 if boundary */
    int edge_v[3][2];  /* the two vertices of each edge */
} Face;

static Vec3 V[MAXV];   static int nV;
static Face  F[MAXF];  static int nF;

/* ---------------- tiny vector helpers ---------------- */
static Vec3 sub3(Vec3 a, Vec3 b){ Vec3 r={a.x-b.x,a.y-b.y,a.z-b.z}; return r; }
static Vec3 crs3(Vec3 a, Vec3 b){
    Vec3 r={a.y*b.z-a.z*b.y, a.z*b.x-a.x*b.z, a.x*b.y-a.y*b.x}; return r;
}
static double dot3(Vec3 a, Vec3 b){ return a.x*b.x+a.y*b.y+a.z*b.z; }
static double len3(Vec3 a){ return sqrt(dot3(a,a)); }
static Vec3 nrm3(Vec3 a){ double l=len3(a); Vec3 r={a.x/l,a.y/l,a.z/l}; return r; }

/* ---------------- OBJ loader (v / f, triangulated on the fly) -------- */
static void load_obj(const char *path)
{
    FILE *fp = fopen(path, "r");
    if (!fp) { fprintf(stderr, "cannot open %s\n", path); exit(1); }
    char line[4096];
    while (fgets(line, sizeof line, fp)) {
        if (line[0]=='v' && (line[1]==' '||line[1]=='\t')) {
            if (nV >= MAXV) { fprintf(stderr,"too many vertices\n"); exit(1); }
            sscanf(line+2, "%lf %lf %lf", &V[nV].x,&V[nV].y,&V[nV].z);
            nV++;
        } else if (line[0]=='f' && (line[1]==' '||line[1]=='\t')) {
            int idx[64], ni=0; char *p=line+1, *q;
            while ((q = strtok(p, " \t\r\n"))) {
                p = NULL;
                int i = atoi(q);            /* OBJ is 1-based; ignore /vt /vn */
                if (i < 0) i = nV + i + 1;  /* negative = relative */
                if (i >= 1 && i <= nV) idx[ni++] = i-1;
                if (ni >= 64) break;
            }
            /* fan-triangulate polygons */
            for (int k = 1; k+1 < ni; k++) {
                if (nF >= MAXF) { fprintf(stderr,"too many faces\n"); exit(1); }
                F[nF].v[0]=idx[0]; F[nF].v[1]=idx[k]; F[nF].v[2]=idx[k+1];
                F[nF].adj[0]=F[nF].adj[1]=F[nF].adj[2]=-1;
                nF++;
            }
        }
    }
    fclose(fp);
    if (nF == 0) { fprintf(stderr,"no faces in %s\n", path); exit(1); }
}

/* ---------------- face adjacency via shared edges ---------------- */
static void build_adjacency(void)
{
    /* hash edges (min,max vertex pair) -> face */
    #define HB 1<<20
    typedef struct { int a,b,f,e; int used; } Ent;
    static Ent *tab;
    tab = calloc(HB, sizeof(Ent));
    #define HSH(a,b) (((unsigned)(a)*2654435761u ^ (unsigned)(b)*40503u) & (HB-1))

    for (int f = 0; f < nF; f++)
        for (int e = 0; e < 3; e++) {
            int a = F[f].v[e], b = F[f].v[(e+1)%3];
            if (a > b) { int t=a; a=b; b=t; }
            unsigned h = HSH(a,b);
            while (tab[h].used) h = (h+1) & (HB-1);
            tab[h].used=1; tab[h].a=a; tab[h].b=b; tab[h].f=f; tab[h].e=e;
        }
    for (int f = 0; f < nF; f++)
        for (int e = 0; e < 3; e++) {
            int a = F[f].v[e], b = F[f].v[(e+1)%3];
            if (a > b) { int t=a; a=b; b=t; }
            unsigned h = HSH(a,b);
            while (tab[h].used && !(tab[h].a==a && tab[h].b==b)) h = (h+1)&(HB-1);
            if (!tab[h].used) continue;
            int f2 = tab[h].f, e2 = tab[h].e;
            if (f2 != f) { F[f].adj[e] = f2; F[f2].adj[e2] = f; }
        }
    free(tab);
}

/* ---------------- per-surface flattening ---------------- */

/* Place triangle (p0,p1 shared with previous face) flat in 2D.
 * Given 2D positions of the shared edge, compute 2D position of the
 * third vertex using true 3D edge lengths.  Exact local isometry. */
static Vec2 unfold_vertex(Vec2 p0, Vec2 p1, double l02, double l12, int flip)
{
    double ex = p1.x - p0.x, ey = p1.y - p0.y;
    double L2 = ex*ex + ey*ey;
    if (L2 < 1e-30) L2 = 1e-30;
    double x = (l02*l02 - l12*l12 + L2) / (2.0*L2);   /* law of cosines */
    double t = x*(1.0-x)*L2;
    double y = sqrt(t > 0 ? t : 0);
    if (flip) y = -y;
    Vec2 r = { p0.x + x*ex - y*ey, p0.y + x*ey + y*ex };
    return r;
}

/* Relax a flat patch toward preserving both edge lengths and areas.
 * Iterative local/global (ARAP-flavored): each triangle re-fits its
 * corners to its best-fit rotation of the 3D shape, then vertices are
 * averaged.  This spreads distortion instead of piling it at the seed. */
static void relax(int *faces, int nf, Vec2 *P, int *flocal, int nlocal)
{
    (void)flocal; (void)nlocal;
    for (int it = 0; it < 60; it++) {
        /* accumulate best-fit 2D targets per vertex */
        static double sx[MAXV], sy[MAXV]; static int cnt[MAXV];
        memset(cnt, 0, sizeof(int)*(size_t)nV);
        for (int k = 0; k < nf; k++) {
            int f = faces[k];
            /* 3D edge vectors */
            Vec3 e0 = sub3(V[F[f].v[1]], V[F[f].v[0]]);
            Vec3 e1 = sub3(V[F[f].v[2]], V[F[f].v[0]]);
            /* current 2D edge vectors */
            double a0x = P[F[f].v[1]].x - P[F[f].v[0]].x;
            double a0y = P[F[f].v[1]].y - P[F[f].v[0]].y;
            double a1x = P[F[f].v[2]].x - P[F[f].v[0]].x;
            double a1y = P[F[f].v[2]].y - P[F[f].v[0]].y;
            /* best-fit rotation angle of 2D onto 3D (projection-free:
             * solve for rotation minimizing sum |R*e2d - e3d_xy|^2 using
             * the 2D triangle's own frame vs the 3D triangle's frame) */
            double c00=a0x, c01=a0y, c10=a1x, c11=a1y;
            /* target: 3D triangle flattened in its own best-fit plane */
            Vec3 n = nrm3(crs3(e0,e1));
            Vec3 u = nrm3(e0);
            Vec3 w = crs3(n,u);
            double t0x = len3(e0), t0y = 0.0;
            double t1x = dot3(e1,u), t1y = dot3(e1,w);
            /* solve 2x2 least squares: R * [c] ~ [t]  =>  R = T*C^T(CC^T)^-1 */
            double det = c00*c11 - c01*c10;
            if (fabs(det) < 1e-30) continue;
            double i00 =  c11/det, i01 = -c01/det;
            double i10 = -c10/det, i11 =  c00/det;
            /* R = T * C^{-1} (as complex-ish 2x2) */
            double r00 = t0x*i00 + t0y*i10, r01 = t0x*i01 + t0y*i11;
            double r10 = t1x*i00 + t1y*i10, r11 = t1x*i01 + t1y*i11;
            /* rotated targets for the three corners */
            Vec2 src[3], dst[3];
            src[0] = P[F[f].v[0]];
            src[1].x = src[0].x + a0x; src[1].y = src[0].y + a0y;
            src[2].x = src[0].x + a1x; src[2].y = src[0].y + a1y;
            for (int j = 0; j < 3; j++) {
                double dx = src[j].x - src[0].x, dy = src[j].y - src[0].y;
                dst[j].x = src[0].x + r00*dx + r01*dy;
                dst[j].y = src[0].y + r10*dx + r11*dy;
            }
            for (int j = 0; j < 3; j++) {
                int vi = F[f].v[j];
                sx[vi] += dst[j].x; sy[vi] += dst[j].y; cnt[vi]++;
            }
        }
        /* average = new positions (Jacobi step, damped) */
        for (int k = 0; k < nf; k++)
            for (int j = 0; j < 3; j++) {
                int vi = F[k >= 0 ? faces[k] : 0].v[j];
                if (cnt[vi]) {
                    P[vi].x += 0.5 * (sx[vi]/cnt[vi] - P[vi].x);
                    P[vi].y += 0.5 * (sy[vi]/cnt[vi] - P[vi].y);
                }
            }
    }
}

/* Flatten one connected component.  Returns max relative distortion. */
static double flatten_surface(int *faces, int nf, const char *outdir, int id)
{
    /* collect vertices of this patch */
    static int vmap[MAXV];          /* global -> local */
    static int vlist[MAXV];
    int nloc = 0;
    memset(vmap, -1, sizeof(int)*(size_t)nV);
    for (int k = 0; k < nf; k++)
        for (int j = 0; j < 3; j++) {
            int g = F[faces[k]].v[j];
            if (vmap[g] < 0) { vmap[g] = nloc; vlist[nloc++] = g; }
        }
    (void)vlist;

    static Vec2 P[MAXV];
    /* seed: first face placed axis-aligned with true lengths */
    int f0 = faces[0];
    double l01 = len3(sub3(V[F[f0].v[1]], V[F[f0].v[0]]));
    double l02 = len3(sub3(V[F[f0].v[2]], V[F[f0].v[0]]));
    P[F[f0].v[0]] = (Vec2){0,0};
    P[F[f0].v[1]] = (Vec2){l01,0};
    P[F[f0].v[2]] = unfold_vertex(P[F[f0].v[0]], P[F[f0].v[1]], l02,
                     len3(sub3(V[F[f0].v[2]], V[f0 < nF ? f0 : f0].v[1 < 3 ? 1 : 1]])), 0);
    /* fix the seed's third vertex properly (edge 0->2 vs 1->2) */
    P[F[f0].v[2]] = unfold_vertex(P[F[f0].v[0]], P[F[f0].v[1]], l02,
                     len3(sub3(V[F[f0].v[2]], V[F[f0].v[1]])), 0);

    /* BFS across shared edges, unfolding each triangle */
    static char done[MAXF]; memset(done, 0, nf);
    static int queue[MAXF]; int qh = 0, qt = 0;
    done[f0] = 1; queue[qt++] = f0;
    while (qh < qt) {
        int f = queue[qh++];
        for (int e = 0; e < 3; e++) {
            int g = F[f].adj[e];
            if (g < 0 || done[g]) continue;
            /* is g in this patch? */
            int inpatch = 0;
            for (int k = 0; k < nf; k++) if (faces[k] == g) { inpatch = 1; break; }
            if (!inpatch) continue;
            /* shared edge vertices in f: (v[e], v[e+1]) */
            int a = F[f].v[e], b = F[f].v[(e+1)%3];
            int c = F[f].v[(e+2)%3];          /* opposite in f */
            /* corresponding opposite vertex in g */
            int gc = -1;
            for (int j = 0; j < 3; j++)
                if (F[g].v[j] != a && F[g].v[j] != b) gc = F[g].v[j];
            if (gc < 0) continue;
            double l1 = len3(sub3(V[gc], V[a]));
            double l2 = len3(sub3(V[gc], V[b]));
            /* fold to the opposite side of the shared edge from c */
            Vec2 pa = P[a], pb = P[b], pc = P[c];
            double cross = (pb.x-pa.x)*(pc.y-pa.y) - (pb.y-pa.y)*(pc.x-pa.x);
            int flip = (cross > 0) ? 1 : 0;   /* place g's apex on other side */
            P[gc] = unfold_vertex(pa, pb, l1, l2, flip);
            done[g] = 1; queue[qt++] = g;
        }
    }

    /* relaxation: spread distortion evenly */
    relax(faces, nf, P, NULL, 0);

    /* measure worst relative edge-length error */
    double worst = 0;
    for (int k = 0; k < nf; k++)
        for (int j = 0; j < 3; j++) {
            int a = F[faces[k]].v[j], b = F[faces[k]].v[(j+1)%3];
            double l3 = len3(sub3(V[a], V[b]));
            double l2 = hypot(P[a].x-P[b].x, P[a].y-P[b].y);
            if (l3 > 1e-12) {
                double err = fabs(l2-l3)/l3;
                if (err > worst) worst = err;
            }
        }

    /* write output: one file per surface ("page") */
    char path[512];
    snprintf(path, sizeof path, "%s/surface_%03d.uv", outdir, id);
    FILE *out = fopen(path, "w");
    if (!out) { fprintf(stderr, "cannot write %s\n", path); exit(1); }
    fprintf(out, "# surface %d: %d faces, worst edge-length error %.4f%%\n",
            id, nf, worst*100.0);
    for (int k = 0; k < nf; k++) {
        fprintf(out, "f");
        for (int j = 0; j < 3; j++) {
            int g = F[faces[k]].v[j];
            fprintf(out, " %.6f %.6f", P[g].x, P[g].y);
        }
        fprintf(out, "\n");
    }
    fclose(out);
    printf("surface %03d: %4d faces, %4d verts, worst length error %6.2f%%  -> %s\n",
           id, nf, nloc, worst*100.0, path);
    return worst;
}

/* ---------------- find components and drive ---------------- */
int main(int argc, char **argv)
{
    if (argc < 3) {
        fprintf(stderr, "usage: %s model.obj outdir\n", argv[0]);
        return 1;
    }
    load_obj(argv[1]);
    build_adjacency();

    static char seen[MAXF]; memset(seen, 0, nF);
    static int faces[MAXF];
    int id = 0;
    for (int s = 0; s < nF; s++) {
        if (seen[s]) continue;
        int nf = 0, qh = 0, qt = 0;
        seen[s] = 1; faces[nf++] = s; /* queue reuse */
        static int queue[MAXF];
        queue[qt++] = s;
        while (qh < qt) {
            int f = queue[qh++];
            for (int e = 0; e < 3; e++) {
                int g = F[f].adj[e];
                if (g >= 0 && !seen[g]) { seen[g] = 1; faces[nf++] = g; queue[qt++] = g; }
            }
        }
        id++;
        flatten_surface(faces, nf, argv[2], id);
    }
    printf("done: %d surfaces\n", id);
    return 0;
}
```

## Notes on what "preserving distances and areas" means here

- **Exact where possible.** Every triangle is unfolded with its true 3D edge lengths (law of cosines), so within any single triangle, distances and areas are preserved *exactly*. On a genuinely developable surface (a cylinder side, a cone, a flat sheet with cuts), the whole patch comes out with essentially zero distortion.
- **Impossible where impossible.** A closed sphere or a strongly curved patch has no distortion-free flat map — this is a theorem, not a limitation of the code. The relaxation pass (a simplified ARAP local/global iteration) redistributes that unavoidable distortion evenly instead of letting it pile up near the seed triangle, and the program reports the worst residual edge-length error per surface so you can see how "unfoldable" each patch actually is.
- **One page per surface.** Each connected component gets its own `.uv` file, so overlapping layouts between different surfaces are irrelevant, as you said.

If you need a different tradeoff — e.g., strict area preservation (authalic maps) instead of length preservation, or conformal (angle-preserving) flattening via LSCM — say so and I'll swap the objective in the relaxation step; the loader, component-finding, and per-page output all stay the same.

