/* ---------------- per-surface flattening ---------------- */

/* Place a triangle flat in 2D.  Given 2D positions of a shared edge,
 * compute the 2D position of the third vertex using true 3D edge
 * lengths.  Exact local isometry. */
static Vec2 unfold_vertex(Vec2 p0, Vec2 p1, double l02, double l12, int flip)
{
